export type MuscleGroup =
  | 'chest'
  | 'front_delts'
  | 'side_delts'
  | 'rear_delts'
  | 'lats'
  | 'traps'
  | 'lower_back'
  | 'biceps'
  | 'triceps'
  | 'forearms'
  | 'abs'
  | 'obliques'
  | 'quads'
  | 'hamstrings'
  | 'glutes'
  | 'calves';

export type Equipment =
  | 'barbell'
  | 'dumbbell'
  | 'machine'
  | 'cable'
  | 'bodyweight'
  | 'kettlebell'
  | 'band'
  | 'smith'
  // apparatus — not every exercise's primary equipment, but often required
  // alongside it (a barbell bench press needs a barbell AND a bench). See
  // impliedEquipment() in exerciseRelations.ts.
  | 'bench'
  | 'squat_rack'
  | 'pull_up_bar'
  | 'dip_bars';

/**
 * The individual pieces of kit shown in onboarding/Profile equipment picker.
 * Deliberately more granular than the old three-tier "full gym / dumbbells at
 * home / bodyweight" picker — a bench and a pull-up bar are wildly different
 * things to have access to. Bodyweight is left out: it needs nothing, so it's
 * always available and never a checkbox.
 */
export const EQUIPMENT_OPTIONS: { value: Equipment; label: string }[] = [
  { value: 'barbell', label: 'Barbell' },
  { value: 'bench', label: 'Bench' },
  { value: 'squat_rack', label: 'Squat rack' },
  { value: 'dumbbell', label: 'Dumbbells' },
  { value: 'pull_up_bar', label: 'Pull-up bar' },
  { value: 'dip_bars', label: 'Dip bars' },
  { value: 'cable', label: 'Cable machine' },
  { value: 'machine', label: 'Machines' },
  { value: 'kettlebell', label: 'Kettlebell' },
  { value: 'band', label: 'Resistance bands' },
  { value: 'smith', label: 'Smith machine' },
];

/** every piece of kit, including bodyweight — the "full gym" default */
export const ALL_EQUIPMENT: Equipment[] = [
  ...EQUIPMENT_OPTIONS.map((e) => e.value),
  'bodyweight',
];

import type { MovementPattern } from '@/data/patterns';

export type Category = 'chest' | 'back' | 'shoulders' | 'arms' | 'legs' | 'core' | 'full_body';

export interface Exercise {
  id: string;
  name: string;
  category: Category;
  /** push / pull / legs / core split bucket, used by the plan generator */
  split: 'push' | 'pull' | 'legs' | 'core' | 'full_body';
  primaryMuscles: MuscleGroup[];
  secondaryMuscles: MuscleGroup[];
  equipment: Equipment;
  mechanic: 'compound' | 'isolation';
  difficulty: 'beginner' | 'intermediate' | 'advanced';
  /**
   * The movement pattern this belongs to. Coaching that is true of the whole
   * pattern lives in data/patterns.ts rather than being repeated per exercise,
   * and the planner and balance analysis reason in these terms too.
   */
  pattern: MovementPattern;
  instructions: string[];
  tips: string[];
  /**
   * Errors specific to this lift, shown above the pattern's own. Only worth
   * filling in where the lift has a failure mode its pattern does not cover.
   */
  mistakes?: string[];
  /**
   * True for an exercise the user created themselves. Custom exercises are
   * excluded from the auto-planner and from variation/substitution scoring
   * against each other — they're additions to the picker, not new data the
   * rest of the app reasons about.
   */
  isCustom?: boolean;
}

