/* ================================================================== */
/* Aggregation + helpers                                              */
/* ================================================================== */

export const EXERCISES: Exercise[] = [
  ...CHEST,
  ...CHEST_EXTRA,
  ...BACK,
  ...BACK_EXTRA,
  ...SHOULDERS,
  ...SHOULDERS_EXTRA,
  ...ARMS,
  ...ARMS_EXTRA,
  ...LEGS,
  ...LEGS_EXTRA,
  ...CORE,
  ...CORE_EXTRA,
  ...GAPS,
];

/**
 * Exercises the user has created themselves. This lives here, alongside the
 * built-in library, rather than only in the workout store, because
 * getExerciseById and friends are called as plain functions all over the
 * app (screens, the store itself, share cards) with no store access at
 * hand. The workout store owns and persists the real data and keeps this
 * mirror in sync via setCustomExercises whenever it changes.
 */
let customExercises: Exercise[] = [];

export function setCustomExercises(list: Exercise[]) {
  customExercises = list;
}

export function getCustomExercises(): Exercise[] {
  return customExercises;
}

/** Built-in exercises plus whatever the user has added themselves. */
export function allExercises(): Exercise[] {
  return customExercises.length ? [...EXERCISES, ...customExercises] : EXERCISES;
}

export function getExerciseById(id: string): Exercise | undefined {
  return EXERCISES.find((e) => e.id === id) ?? customExercises.find((e) => e.id === id);
}

export function exercisesByEquipment(allowed: Equipment[]): Exercise[] {
  return EXERCISES.filter((e) => allowed.includes(e.equipment));
}

export function exercisesForMuscle(muscle: MuscleGroup): Exercise[] {
  return EXERCISES.filter(
    (e) => e.primaryMuscles.includes(muscle) || e.secondaryMuscles.includes(muscle)
  );
}

/** All muscles an exercise touches, primary first. */
export function allMusclesFor(exercise: Exercise): MuscleGroup[] {
  return [...exercise.primaryMuscles, ...exercise.secondaryMuscles];
}
